#!/usr/bin/env python3
"""Publish only evidence from the exact final cartridge, including regressions."""
import base64,csv,hashlib,html,json,shutil,struct,subprocess,zipfile
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parents[1];B=R/'build/native110';RUN=B/'hot-play';D=R/'docs/native-assets-0.5.110';G=R/'generated';D.mkdir(parents=True,exist_ok=True)
def read(p):return json.loads(p.read_text())
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
build=read(G/'native-build.json');measured=read(RUN/'build.json');assert build['rom_sha256']==measured['rom_sha256'] and sha(Path(build['rom']))==measured['rom_sha256'] and sha(Path(build['elf']))==measured['elf_sha256']
old=read(G/'play-validation-0.5.109.json');s=read(RUN/'summary.json');trace=[json.loads(x) for x in (RUN/'trace.jsonl').read_text().splitlines()];last=trace[-1]
rows=list(csv.DictReader((RUN/'commits.csv').open()));clock=280896/16777216
active=[r for r in rows if r['playing']=='1' and r['presentation']=='0' and r['demo']=='0'];start=next(i for i,r in enumerate(active) if int(r['live0']));active=active[start:]
def interval(rs):
 a,b=rs[0],rs[-1];secs=(int(b['lcd'])-int(a['lcd']))*clock;n=int(b['commits'])-int(a['commits']);return dict(lcd_start=int(a['lcd']),lcd_end=int(b['lcd']),commits=n,seconds=secs,fps=n/secs,camera_start=int(a['camera_x']),camera_end=int(b['camera_x']))
def pacing(rs):
 gaps=np.array([int(b['lcd'])-int(a['lcd']) for a,b in zip(rs,rs[1:])])*clock*1000
 return dict(intervals=len(gaps),median_ms=float(np.median(gaps)),p95_ms=float(np.percentile(gaps,95)),p99_ms=float(np.percentile(gaps,99)),max_ms=float(gaps.max()),over_100ms=int((gaps>=100).sum()))
scenes={i:[r for r in active if r['scene']==str(i)] for i in (0,1)}
perf=dict(overall=s['active_play'],m1_active=interval(scenes[0]),m2_observed=interval(scenes[1]),white_frames=s['execution']['all_white_game_frames'],game_lcd_frames=s['execution']['game_lcd_frames'],late_transfers=last['video.late_transfers'],bg_backend='Permanent4bpp; joint index atlas plus14 regional RGB palettes; nearest two planes; compiled dynamic boundary nibble maps; dirty DMA')
stack=read(B/'stack.json');memory=dict(old['memory']);memory.update(rom_bytes=build['rom_bytes'],rom_free=33554432-build['rom_bytes'],ewram_used=260780,ewram_free=262144-260780,iwram_before_stack_used=26144,iwram_before_reserved_stack_free=26368-26144,observed_main_stack=stack['main']['used'],observed_irq_stack=stack['irq']['used'])
front=read(B/'final-frontend/summary.json');snapshots={}
for frame in (6428,9000,25000):
 p=B/f'final-snap-{frame}';snapshots[str(frame)]={**read(p/'verification.json'),**read(p/'object-hardware.json')}
 for name in ['verification.json','object-hardware.json','source-background.png','native-background.png']:shutil.copyfile(p/name,D/f'{frame}-{name}')
ring=read(B/'final-audio/verification.json');assert ring['rom_sha256']==build['rom_sha256'] and ring['restart_mismatches']==0
assert last['app.error']==0 and last['audio.fault']==0
assert front['demo']['last']['app.error']==0x0b1e0000
for name in ['tutorial','pause','link-cancel','ranking']:assert front[name]['exit_code']==0
manifest=read(G/'native-background/manifest.json');packing=read(G/'native-background/packing.json')
new_tradeoffs=['BG uses jointly quantized index patterns and up to12 banks x15 opaque RGB555 entries per region; stronger posterization than109.', 'Only two nearest active source BG planes; an additional distant decorative layer is omitted versus109 three-plane default.', 'Local BG colour cycling/interpolation is frozen into regional palettes. Uniform global fade uses16 hardware steps; HUD/OBJ retain original CPU fades.', 'Precompiled interiors have no runtime RGB search. Moving-column/patch/clear boundaries still assemble four preconverted4x4 fragments with compiled nibble maps. Full elimination of runtime boundary composition is NOT complete.']
report={k:old[k] for k in ['fixed_frame_bytes','input_method','lcd_clock','audio_settings','pcm_cache']}
report.update(version='0.5.110',status='experimental; aggregate FPS regression; nominal30 target not achieved',rom_sha256=build['rom_sha256'],elf_sha256=build['elf_sha256'],fingerprint=build['fingerprint'],complete_port=False,m1_clear_verified=True,target_fps=30,target_met=False,verified_campaign_scope='Input-only mGBA0.10.2 HLE,36000LCD: M1 clear/results to partial M2; no M2 clear/fullcampaign/physical2P/helicopter-defeat claim.',memory=memory,performance=perf,frame_pacing={f'm{i+1}':pacing(v) for i,v in scenes.items()},scene_transitions=[{'lcd':int(r['lcd']),'scene':int(r['scene']),'ticks':int(r['ticks'])} for i,r in enumerate(active) if not i or r['scene']!=active[i-1]['scene']],object_palette_policy=old['object_palette_policy'],visual_tradeoffs=old['visual_tradeoffs']+new_tradeoffs,implemented_optimizations=['712 source regions converted to complete GBA4bpp windows/maps; universal index map shared across14 regional palettes','Permanent320-tile BG3 HUD with glyph-combination cache and exact HUD RGB','OBJ immutable ROM uploads retain physical VRAM positions across absence; OAM indices remapped','Uniform BG fades useBLDCNT/BLDY; frontend resets blend registers','Coalesced adjacent uploads and dirty map-row spans; small transfers use CPU stores','Hot BG/OBJ/HUD work in bounded IWRAM; unused OBJ FIX fallback removed'],renderer_features={'permanent_bg4_commits':last['video.bg4_commits'],'permanent_hud_commits':last['video.hud_commits'],'native_asset_cache_misses':last['video.backgrounds.native_tiles'],'boundary_cache_misses':last['video.backgrounds.boundary_tiles'],'counter_note':'These count unresolved tile-cache requests, not all rendered cells or DMA transfers.'},offline_region_compiler={'rom_linked':True,'regions':manifest['regions'],'source_cells':manifest['source_cells'],'native_tiles':manifest['native_tiles'],'map_entries':manifest['map_entries'],'palette_profiles':manifest['profiles'],'format':manifest['format'],'runtime_boundary_composition_remaining':True,'all_authored_regions_not_route_samples':True},hardware_snapshots=snapshots,frontend_results={n:dict(exit_code=x['exit_code'],error=x['last']['app.error'],scene=x['last']['scene.program'],tick=x['last']['world.ticks']) for n,x in front.items()},frontend_verified_paths=['logo/title','tutorial to gameplay','pause/resume','ranking/title','no-peer link cancel','first demo/ranking until known second-demo scene4tick112 fault'],catalog_decode={'reused_from':'0.5.109','reason':'All13 checked audio/player asset files unchanged; new audio engine code not introduced','baseline_evidence':old['catalog_decode']},audible_output={'captured_samples_stereo':s['execution']['audio_samples'],'capture_rate':s['execution']['audio_rate'],'captured_seconds':s['execution']['audio_samples']/s['execution']['audio_rate'],'peak':s['execution']['audio_peak'],'audio_fault':last['audio.fault'],'ring_continuity':ring,'limitation':'Short waveform capture plus read-only600-second FIFO continuity. No fullcampaign listening or physical GBA evidence.'},comparison={'baseline_version':'0.5.109','baseline_performance':old['performance'],'method':'Same input-only state-aware controller,36000LCD each. Keys respond to simulation state; not identical absolute LCD-frame inputs. Different final M2 positions; per-scene and matched-tick views provided, no full-campaign average.'},regressions={'asset_codec':(B/'asset-roundtrip.log').read_text().strip(),'palette_and_obj':(B/'final-regressions.log').read_text().strip(),'native_bg_state':(B/'palette-state-test.log').read_text().strip(),'preserved':read(B/'preserved.json')},priority='Aggregate FPS regressed: optimize dynamic boundaries, BG planning and OBJ preparation before promoting; maintain measured109 baseline for comparison. Then second demo and fullcampaign/physical2P.',evidence='docs/native-assets-0.5.110/')
base_rows=list(csv.DictReader((R/'build/rom109/audio-only/commits.csv').open()));matched=[]
for scene,lo,hi in [(0,500,2000),(0,2000,3000),(0,3000,5200),(1,6000,8000),(1,8000,11000)]:
 row=dict(scene=scene,ticks=[lo,hi])
 for key,rs in [('baseline',base_rows),('candidate',rows)]:
  q=[r for r in rs if r['scene']==str(scene) and r['playing']=='1' and r['presentation']=='0' and r['demo']=='0' and lo<=int(r['ticks'])<=hi];row[key]=interval(q) if len(q)>1 else None
 matched.append(row)
report['comparison']['matched_ticks']=matched
dump(G/'play-validation-0.5.110.json',report);dump(D/'validation.json',report);dump(D/'build.json',build);dump(D/'asset-manifest-summary.json',{k:v for k,v in manifest.items() if k not in ['rows','metrics']});dump(D/'packing.json',packing)
for name in ['asset-roundtrip.log','final-regressions.log','palette-state-test.log','stack.json','preserved.json']:shutil.copyfile(B/name,D/name)
